var bot = k.mix('#fbe3b0', '#c9c2b8', d);
for (var i = 0; i < 8; i++) {
  k.rect(0, i * 70, 1600, 72, k.mix(top, bot, i / 7), {lw: 0});
}
k.glow(1200, 330, 230 + b * 90, '#fff2c0', 0.4 + b * 0.3);
k.cloud(300 + Math.sin(t * 0.1) * 40, 150, 260, '#fbf6e9', {dark: d});
k.cloud(900 + Math.sin(t * 0.08) * 50, 100, 200, '#fbf6e9', {dark: d});
if (b > 0.5) { k.cloud(1350, 190, 180, '#fbf6e9', {dark: 0}); }

var d = m.decay, b = m.bloom;
var idle = p.idle === undefined ? 0.35 : p.idle;
var coats = ['#e4572e', '#2e86ab', '#f2b134', '#7b4b94'];
var nWalk = Math.max(1, Math.round(4 * (1 - idle)));
k.stroll(100, 1000, 870, nWalk, t, {size: 110, coats: coats, speed: 0.6 + m.wind * 0.5, hat: b > 0.5, depth: 0.2});
var nIdle = 1 + Math.round(idle * 4);
for (var i = 0; i < 5; i++) {
  if (i >= nIdle) { break; }
  var x = 1120 + i * 70 + k.rand(i + 3) * 30;
  var y = 868 + (i % 2) * 10;
  var bow = k.clamp(0.5 + d * 0.5 - b * 0.3, 0, 1);
  var sway = Math.sin(t * 0.8 + i * 1.7) * 2;
  k.figure(x + sway, y, 105 + k.rand(i) * 10, coats[i % 4], {sit: 0, arms: b > 0.5 ? 0.6 : 0, bowed: bow, hair: '#2a1d1d', hat: b > 0.5 ? 'cone' : undefined});
  if (b > 0.5) {
    k.line([[x + 22, y - 50], [x + 40, y - 95]], 5, '#8a5a2b');
    k.rect(x + 32, y - 100, 18, 8, '#9aa0a6');
  }
}
if (d > 0.4) {
  k.alpha(0.5, function () {
    k.blob(1250, 886, 200, 10, '#15111c');
  });
}

