  k.figure(x + sway, y, 105 + k.rand(i) * 10, coats[i % 4], {sit: 0, arms: b > 0.5 ? 0.6 : 0, bowed: bow, hair: '#2a1d1d', hat: hats[(i + 1) % 4]});
